/* Packs the compiled CommonJS engine (dist/src) into one browser script that defines window.RepublicEngine.
 * No bundler dependency: each module is wrapped in a function and resolved through a small require shim.
 * Usage: node scripts/bundle-engine.cjs [--check] */
const fs=require('node:fs');
const path=require('node:path');
const root=path.join(__dirname,'..');
const distRoot=path.join(root,'dist','src');
const entry='game/browser-bridge.js';
const output=path.join(root,'engine','republic-engine.js');

function resolveFile(from,request){
  const joined=path.posix.normalize(path.posix.join(path.posix.dirname(from),request));
  for(const candidate of [`${joined}.js`,`${joined}/index.js`])if(fs.existsSync(path.join(distRoot,candidate)))return candidate;
  throw new Error(`Cannot resolve ${request} from ${from}`);
}

/** Only modules reachable from the entry are bundled, so stale files left in dist/ never ship. */
function collect(start){
  const seen=new Map(),queue=[start];
  while(queue.length){
    const file=queue.shift();if(seen.has(file))continue;
    const code=fs.readFileSync(path.join(distRoot,file),'utf8').replace(/\r\n/g,'\n').replace(/\n\/\/# sourceMappingURL=.*$/,'');
    seen.set(file,code);
    for(const match of code.matchAll(/require\("(\.[^"]+)"\)/g))queue.push(resolveFile(file,match[1]));
  }
  return [...seen.entries()].sort(([a],[b])=>a.localeCompare(b));
}

if(!fs.existsSync(path.join(distRoot,entry))){console.error('Compiled engine not found. Run `npm run build:core` first.');process.exit(1);}
const modules=collect(entry).map(([file,code])=>`${JSON.stringify(file)}:function(module,exports,require){\n${code}\n}`);
const bundle=`/* REPUBLIC: 543 simulation engine — generated by scripts/bundle-engine.cjs from src/. Do not edit by hand. */
(function(global){
  "use strict";
  var factories={
${modules.join(',\n')}
  };
  var cache={};
  function resolve(from,request){
    var parts=from.split('/');parts.pop();
    request.split('/').forEach(function(p){if(p==='..')parts.pop();else if(p!=='.')parts.push(p);});
    var id=parts.join('/');
    return factories[id+'.js']?id+'.js':id+'/index.js';
  }
  function load(id){
    if(cache[id])return cache[id].exports;
    if(!factories[id])throw new Error('Engine module not found: '+id);
    var module=cache[id]={exports:{}};
    factories[id].call(module.exports,module,module.exports,function(request){return load(resolve(id,request));});
    return module.exports;
  }
  global.RepublicEngine=Object.freeze(load(${JSON.stringify(entry)}));
})(typeof globalThis!=='undefined'?globalThis:this);
`;

if(process.argv.includes('--check')){
  const current=fs.existsSync(output)?fs.readFileSync(output,'utf8').replace(/\r\n/g,'\n'):'';
  if(current!==bundle){console.error('engine/republic-engine.js is out of date. Run `npm run build:engine` and commit the result.');process.exit(1);}
  console.log('Engine bundle is up to date.');
}else{
  fs.mkdirSync(path.dirname(output),{recursive:true});
  fs.writeFileSync(output,bundle);
  console.log(`Wrote ${path.relative(root,output)} (${modules.length} modules, ${Math.round(bundle.length/1024)} KB).`);
}
